import net.civeira.phylax.feature.observe.source.ObservedOriginReader;
import net.civeira.phylax.feature.observe.source.ObservedSourceSyncService;

/**
 * Initial data of the observability hub (trait multitenant-observability), after InstallAccess:
 * <ul>
 * <li>Roles OBSERVABILITY_READER and OBSERVABILITY_ADMIN.</li>
 * <li>Client of the viewer ({@code observe-viewer}): public, PKCE, redirect to
 * {@code /observe/callback}, audience the relying party of the API.</li>
 * <li>The ROOT user gets OBSERVABILITY_ADMIN and access to the viewer client.</li>
 * <li>A test user in the main tenant with OBSERVABILITY_READER (it can be disabled).</li>
 * <li>The observed sources of the seeded clients, with the configured ingest keys; the source of
 * the viewer client is disabled (it is not an observed application).</li>
 * </ul>
 * Every step checks what exists, so it also completes a partial installation. The secrets that are
 * not configured are generated and shown once in the log.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class InstallObservability implements MigrationSeed {

  private static final String SEED_CONFIG = "migration/seed/observability-seed.yaml";
  private static final String OIDC_SEED = "migration/seed/oidc-seed.yaml";
  public static final String READER = "OBSERVABILITY_READER";
  public static final String ADMIN = "OBSERVABILITY_ADMIN";

  private final IsolatedConfigLoader configs;
  private final SecureTokenService tokens;
  private final RoleCommandRepositoryGateway roles;
  private final OauthClientCommandRepositoryGateway clients;
  private final TenantCommandRepositoryGateway tenants;
  private final UserCommandRepositoryGateway users;
  private final UserRoleAssignmentCommandRepositoryGateway rolesAssignment;
  private final UserGroupMembershipCommandRepositoryGateway groupsMembership;
  private final ObservedSourceCommandRepositoryGateway sources;
  private final ObservedSourceSyncService sync;
  private final Instance<ObservedOriginReader> readers;

  @Override
  public String id() {
    return "seed/install-observability";
  }

  @Override
  public int order() {
    // After InstallAccess (10), InitialDocument (30) and InstallObserveDocuments (35)
    return 40;
  }

  @Override
  @Transactional
  public void run() {
    install(configs.load(SEED_CONFIG), configs.load(OIDC_SEED));
  }

  void install(final IsolatedConfig config, final IsolatedConfig oidc) {
    Map<String, String> generated = new LinkedHashMap<>();
    Role reader = role(READER);
    Role admin = role(ADMIN);
    OauthClient viewer = viewerClient(config, oidc);

    users.find(UserFilter.builder().name(oidc.getRequiredConfig("oidc.root.name")).build())
        .ifPresent(root -> grant(root, admin, viewer, "root"));

    if (config.getConfig("observability.test-user.enabled", Boolean.class).orElse(Boolean.TRUE)) {
      testUser(config, oidc, generated).ifPresent(user -> grant(user, reader, viewer, "observer"));
    }

    sync.reconcile(readers.stream().toList());
    ingestKey(config, "observability.ingest-keys.ui",
        oidc.getRequiredConfig("oidc.trusted-client.code"));
    ingestKey(config, "observability.ingest-keys.api",
        oidc.getRequiredConfig("oidc.relying-party.code"));
    sources.find(ObservedSourceFilter.builder().code(viewer.getCode()).build())
        .filter(source -> Boolean.TRUE.equals(source.isEnabled()))
        .ifPresent(source -> sources.update(source, source.disable()));
    for (ObservedSource source : sources.list(ObservedSourceFilter.builder().build())) {
      if (!viewer.getCode().equals(source.getCode())) {
        source.getIngestKey()
            .ifPresent(key -> generated.put("ingest key " + source.getCode(), key));
      }
    }

    if (!generated.isEmpty()) {
      StringBuilder message = new StringBuilder();
      generated
          .forEach((key, value) -> message.append("\n  ").append(key).append(": ").append(value));
      log.warn("Observability credentials of {}; they are shown only this time, store them now:{}",
          id(), message);
    }
  }

  private Role role(final String name) {
    return roles.find(RoleFilter.builder().name(name).build())
        .orElseGet(() -> roles.create(Role.create(new RoleChangeSet().newUid().name(name))));
  }

  private OauthClient viewerClient(final IsolatedConfig config, final IsolatedConfig oidc) {
    String code = config.getRequiredConfig("observability.viewer-client.code");
    Optional<OauthClient> existing = clients.find(OauthClientFilter.builder().code(code).build());
    if (existing.isPresent()) {
      return existing.get();
    }
    String audience =
        config.getConfig("observability.viewer-client.audience").filter(value -> !value.isBlank())
            .orElseGet(() -> oidc.getRequiredConfig("oidc.relying-party.code"));
    AllowedLoginRedirects login = AllowedLoginRedirects.builder().newUid()
        .url(config.getRequiredConfig("observability.viewer-client.redirect")).build();
    AllowedLogoutRedirects logout = AllowedLogoutRedirects.builder().newUid()
        .url(config.getRequiredConfig("observability.viewer-client.logout-redirect")).build();
    AllowedAudiences audiences = AllowedAudiences.builder().newUid().audience(audience).build();
    OauthClientChangeSet client =
        new OauthClientChangeSet().newUid().code(code).allowAllScopes(Boolean.TRUE)
            // A browser SPA: public client (no secret) with PKCE.
            .introspectionAllowed(Boolean.FALSE).requirePkce(Boolean.TRUE)
            .tokenEndpointAuthMethod(OauthClientTokenEndpointAuthMethodOptions.NONE)
            .clientCredentialsTokenTtlSeconds(3600).allowedLoginRedirects(List.of(login))
            .allowedLogoutRedirects(List.of(logout)).allowedAudiences(List.of(audiences))
            .subjectType(OauthClientSubjectTypeOptions.PUBLIC)
            .requirePushedAuthorizationRequests(Boolean.FALSE).dpopBoundAccessTokens(Boolean.FALSE)
            .tlsClientCertificateBoundAccessTokens(Boolean.FALSE).enabled(Boolean.TRUE);
    return clients.create(OauthClient.create(client).enable());
  }

  private Optional<User> testUser(final IsolatedConfig config, final IsolatedConfig oidc,
      final Map<String, String> generated) {
    String name = config.getRequiredConfig("observability.test-user.name");
    Optional<User> existing = users.find(UserFilter.builder().name(name).build());
    if (existing.isPresent()) {
      return existing;
    }
    String tenantName = config.getConfig("observability.test-user.tenant")
        .orElseGet(() -> oidc.getRequiredConfig("oidc.tenant.name"));
    Optional<Tenant> tenant = tenants.find(TenantFilter.builder().name(tenantName).build());
    if (tenant.isEmpty()) {
      log.warn("Tenant {} not found: the observability test user is not created", tenantName);
      return Optional.empty();
    }
    String password = config.getConfig("observability.test-user.password")
        .filter(value -> !value.isBlank()).orElseGet(() -> {
          String value = tokens.generate();
          generated.put("password of " + name, value);
          return value;
        });
    UserChangeSet user = new UserChangeSet().newUid().name(name).passwordPlain(password)
        .temporalPassword(
            config.getConfig("observability.test-user.temporal-password", Boolean.class)
                .orElse(Boolean.TRUE))
        .tenant(tenant.get()).enabled(true).useSecondFactors(false);
    return Optional.of(users.create(User.create(user).enable()));
  }

  private void grant(final User user, final Role role, final OauthClient viewer,
      final String groups) {
    boolean member = groupsMembership
        .list(UserGroupMembershipFilter.builder().user(user).oauthClient(viewer).build()).stream()
        .findAny().isPresent();
    if (!member) {
      groupsMembership.create(UserGroupMembership.create(new UserGroupMembershipChangeSet().newUid()
          .user(user).oauthClient(viewer).groups(groups)));
    }
    rolesAssignment.create(UserRoleAssignment.create(new UserRoleAssignmentChangeSet().newUid()
        .user(user).roles(List.of(Roles.builder().newUid().role(role).build()))));
  }

  private void ingestKey(final IsolatedConfig config, final String key, final String code) {
    config.getConfig(key).filter(value -> !value.isBlank())
        .ifPresent(value -> sync.assignIngestKey(code, value));
  }
}
